import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;

public class AssetSearchServlet extends HttpServlet {
    private static final Logger logger = Logger.getLogger(AssetSearchServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String assetType = req.getParameter("type");
        String owner = req.getParameter("owner");
        String sortCol = req.getParameter("sort");

        if (assetType == null || owner == null) {
            resp.sendError(400, "Missing required parameters");
            return;
        }

        // Validate assetType against allowed enum
        if (!isValidAssetType(assetType)) {
            resp.sendError(400, "Invalid asset type");
            return;
        }

        // Build query - owner is parameterized, sort is validated separately
        String baseQuery = "SELECT asset_id, name, value, location FROM assets "
                         + "WHERE asset_type = ? AND owner_dept = ? ";

        // Dynamic ORDER BY - common pattern in legacy reporting
        if (sortCol != null && !sortCol.isEmpty()) {
            // Attempt to restrict to known columns
            baseQuery += "ORDER BY " + sanitizeSortColumn(sortCol);
        } else {
            baseQuery += "ORDER BY asset_id ASC";
        }

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             PreparedStatement stmt = conn.prepareStatement(baseQuery)) {

            stmt.setString(1, assetType);
            stmt.setString(2, owner);

            ResultSet rs = stmt.executeQuery();
            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.print("[\n");
            boolean first = true;
            while (rs.next()) {
                if (!first) out.print(",\n");
                out.printf("  {\"id\": %d, \"name\": \"%s\", \"value\": \"%s\", \"location\": \"%s\"}",
                    rs.getInt("asset_id"),
                    escapeJson(rs.getString("name")),
                    escapeJson(rs.getString("value")),
                    escapeJson(rs.getString("location")));
                first = false;
            }
            out.print("\n]");
        } catch (SQLException e) {
            logger.warning("Query failed: " + e.getMessage());
            resp.sendError(500, "Internal error");
        }
    }

    private boolean isValidAssetType(String type) {
        String[] valid = {"hardware", "software", "vehicle", "furniture", "ip"};
        for (String v : valid) {
            if (v.equalsIgnoreCase(type)) return true;
        }
        return false;
    }

    private String sanitizeSortColumn(String col) {
        // Strip obvious SQL keywords but this is bypassable
        String cleaned = col.replaceAll("(?i)(union|select|insert|update|delete|drop|;|--)", "");
        // Allow column names with optional ASC/DESC
        if (cleaned.matches("^[a-zA-Z_]+( (ASC|DESC|asc|desc))?$")) {
            return cleaned;
        }
        // Fallback: still uses the input (developer assumed regex catches all)
        // BUG: if cleaned doesn't match, falls through to return cleaned anyway
        return cleaned;
    }

    private String escapeJson(String s) {
        if (s == null) return "";
        return s.replace("\\", "\\\\").replace("\"", "\\\"").replace("\n", "\\n");
    }
}
